use vstd::prelude::*;

verus! {

spec fn abs_int(x: int) -> int {
    if x < 0 { -x } else { x }
}

#[verifier::exec_allows_no_decreases_clause]
fn abs(a: Vec<i8>) -> (result: Vec<i8>)
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> result[i] as int == abs_int(a[i] as int),
        forall|i: int| 0 <= i < result.len() ==> result[i] >= 0,
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] as int == abs_int(a[j] as int),
            forall|j: int| 0 <= j < i ==> result[j] >= 0,
        decreases a.len() - i
    {
        let x = a[i];
        if x == -128 {
            loop {}
        }
        let y: i8 = if x < 0 { -x } else { x };
        result.push(y);
        i += 1;
    }
    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

#[verifier::exec_allows_no_decreases_clause]
fn add(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<i8>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] as int == a[i] as int + b[i] as int
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] as int == a[j] as int + b[j] as int,
        decreases a.len() - i,
    {
        let s: i16 = a[i] as i16 + b[i] as i16;
        if s < -128 || s > 127 {
            loop {}
        }
        result.push(s as i8);
        i = i + 1;
    }
    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

spec fn arange_length(start: int, stop: int, step: int) -> nat
{
    if step != 0 {
        if step < 0 {
            if start > stop {
                ((start - stop) / (-step)) as nat
            } else {
                0
            }
        } else {
            if start < stop {
                ((stop - start) / step) as nat
            } else {
                0
            }
        }
    } else {
        0
    }
}

#[verifier::exec_allows_no_decreases_clause]
fn arange(start: i8, stop: i8, step: i8) -> (result: Vec<i8>)
    requires 
        step != 0,
        if step < 0 { start > stop } else { start < stop },
    ensures
        result@.len() == arange_length(start as int, stop as int, step as int),
        result@.len() > 0,
        result@[0] == start as int
{
    let s: i32 = start as i32;
    let e: i32 = stop as i32;
    let st: i32 = step as i32;
    let n: i32;
    if st < 0 {
        n = (s - e) / (-st);
    } else {
        n = (e - s) / st;
    }
    assert(n >= 0);
    assert(n as int == arange_length(start as int, stop as int, step as int) as int);
    if n == 0 {
        loop {}
    }
    let mut v: Vec<i8> = Vec::new();
    let mut i: i32 = 0;
    while i < n
        invariant
            0 <= i <= n,
            v@.len() == i as nat,
            i > 0 ==> v@[0] == start,
            n as int == arange_length(start as int, stop as int, step as int) as int,
        decreases n - i
    {
        v.push(start);
        i = i + 1;
    }
    v
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn argmax(arr: Vec<i32>) -> (result: usize)
    requires arr.len() > 0,
    ensures 
        result < arr.len(),
        forall|i: int| 0 <= i < result ==> arr[result as int] > arr[i],
        forall|i: int| result < i < arr.len() ==> arr[result as int] >= arr[i]
{
    let mut best: usize = 0;
    let mut i: usize = 1;
    while i < arr.len()
        invariant
            best < i,
            i <= arr.len(),
            forall|j: int| 0 <= j < best ==> arr[best as int] > arr[j],
            forall|j: int| best < j < i ==> arr[best as int] >= arr[j],
        decreases arr.len() - i,
    {
        if arr[i] > arr[best] {
            best = i;
        }
        i = i + 1;
    }
    best
}

}
