use vstd::prelude::*;

verus! {

fn argsort(a: Vec<i8>) -> (result: Vec<usize>)
    ensures 
        result.len() == a.len(),
        forall|i: int, j: int| 0 <= i < j < result.len() ==> #[trigger] a@[result@[i] as int] <= #[trigger] a@[result@[j] as int],
{
    let n = a.len();
    let mut result: Vec<usize> = Vec::new();
    let mut k: usize = 0;
    while k < n
        invariant
            result.len() == k,
            k <= n,
            n == a.len(),
            forall|t: int| 0 <= t < k ==> (#[trigger] result@[t]) < n,
        decreases n - k,
    {
        result.push(k);
        k += 1;
    }
    let mut i: usize = 0;
    while i < n
        invariant
            result.len() == n,
            n == a.len(),
            i <= n,
            forall|t: int| 0 <= t < n ==> (#[trigger] result@[t]) < n,
            forall|p: int, q: int| 0 <= p < q < i ==> #[trigger] a@[result@[p] as int] <= #[trigger] a@[result@[q] as int],
        decreases n - i,
    {
        let mut j: usize = i;
        while j > 0 && a[result[j - 1]] > a[result[j]]
            invariant
                result.len() == n,
                n == a.len(),
                i < n,
                j <= i,
                forall|t: int| 0 <= t < n ==> (#[trigger] result@[t]) < n,
                forall|p: int, q: int| 0 <= p < q <= i && p != j && q != j ==> #[trigger] a@[result@[p] as int] <= #[trigger] a@[result@[q] as int],
                forall|q: int| j < q <= i ==> a@[result@[j as int] as int] <= #[trigger] a@[result@[q] as int],
            decreases j,
        {
            let tmp = result[j - 1];
            let rj = result[j];
            result.set(j - 1, rj);
            result.set(j, tmp);
            j -= 1;
        }
        assert forall|p: int, q: int| 0 <= p < q <= i implies #[trigger] a@[result@[p] as int] <= #[trigger] a@[result@[q] as int] by {
            if q == j {
                if p < j - 1 {
                    assert(a@[result@[p] as int] <= a@[result@[j - 1] as int]);
                }
            } else if p == j {
            } else {
            }
        }
        i += 1;
    }
    result
}

}
