use vstd::prelude::*;

verus! {

proof fn lemma_or_u8_u32(x: u8, y: u8)
    ensures (x | y) as u32 == (x as u32 | y as u32),
{
    assert((x | y) as u32 == (x as u32 | y as u32)) by(bit_vector);
}

fn bitwise_or(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] as u32 == (a[i] as u32 | b[i] as u32),
{
    let mut result: Vec<u8> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < result.len() ==> result[j] as u32 == (a[j] as u32 | b[j] as u32),
        decreases a.len() - i,
    {
        let x = a[i];
        let y = b[i];
        let v = x | y;
        proof {
            lemma_or_u8_u32(x, y);
        }
        result.push(v);
        i += 1;
    }
    result
}

}
fn main() {}

