use vstd::prelude::*;

verus! {
/* Matrix type definition - represents an m×n matrix */
pub struct Matrix<T> {
    pub data: Vec<Vec<T>>,
    pub rows: usize,
    pub cols: usize,
}

impl<T: Copy> Matrix<T> {
    pub open spec fn view(self) -> Seq<Seq<T>> {
        self.data@.map(|i: int, row: Vec<T>| row@)
    }

    pub open spec fn wf(self) -> bool {
        &&& self.data.len() == self.rows
        &&& forall|i: int| 0 <= i < self.data.len() ==> self.data[i].len() == self.cols
    }

    pub open spec fn index(self, i: int, j: int) -> T 
        recommends 0 <= i < self.rows && 0 <= j < self.cols && self.wf()
    {
        self.data[i][j]
    }

    pub open spec fn size(self) -> int {
        self.rows * self.cols
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (ret: Matrix<i8>)
    requires 
        a.len() > 0,
        shape.len() == 2,
        shape[0] > 0,
        shape[1] > 0,
        shape[0] as int == a.len() || shape[1] as int == a.len(),
    ensures
        ret.wf(),
        ret.rows == shape[0] as usize,
        ret.cols == shape[1] as usize,
        ret.size() == shape[0] as int * shape[1] as int,
        forall|i: int, j: int| 0 <= i < shape[0] as int && 0 <= j < shape[1] as int ==> {
            if shape[0] as int == a.len() {
                ret.index(i, j) == a[i as int]
            } else {
                ret.index(i, j) == a[j as int]
            }
        }
{
    let m = shape[0] as usize;
    let n = shape[1] as usize;
    let row_mode = m == a.len();
    let mut data: Vec<Vec<i8>> = Vec::new();
    let mut i: usize = 0;
    while i < m
        invariant
            shape.len() == 2,
            m == shape[0] as usize,
            n == shape[1] as usize,
            row_mode == (shape[0] as int == a.len()),
            row_mode ==> m == a.len(),
            !row_mode ==> n == a.len(),
            data.len() == i,
            i <= m,
            forall|k: int| 0 <= k < i ==> #[trigger] data[k].len() == n,
            forall|k: int, jj: int| 0 <= k < i && 0 <= jj < n ==>
                (if row_mode { #[trigger] data[k][jj] == a[k] } else { data[k][jj] == a[jj] }),
        decreases m - i,
    {
        let mut row: Vec<i8> = Vec::new();
        let mut j: usize = 0;
        while j < n
            invariant
                i < m,
                row_mode ==> m == a.len(),
                !row_mode ==> n == a.len(),
                row.len() == j,
                j <= n,
                forall|jj: int| 0 <= jj < j ==>
                    (if row_mode { #[trigger] row[jj] == a[i as int] } else { row[jj] == a[jj] }),
            decreases n - j,
        {
            let v = if row_mode { a[i] } else { a[j] };
            row.push(v);
            j += 1;
        }
        data.push(row);
        i += 1;
    }
    Matrix { data, rows: m, cols: n }
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn center(input: Vec<String>, width: usize) -> (result: Vec<String>)
    requires 
        input.len() > 0,
        forall|i: int| 0 <= i < input.len() ==> input[i]@.len() >= 1,
    ensures
        result.len() == input.len(),
        forall|i: int| 0 <= i < input.len() ==> 
            if input[i]@.len() > width {
                result[i]@.len() == input[i]@.len()
            } else {
                result[i]@.len() == width
            },
        forall|i: int| 0 <= i < input.len() ==> 
            if input[i]@.len() < width {
                let start_pos = (width - input[i]@.len() + 1) / 2;
                result[i]@.skip(start_pos as int).take(input[i]@.len() as int) == input[i]@
            } else {
                true
            }
{
    let mut result: Vec<String> = Vec::new();
    let mut i: usize = 0;
    while i < input.len()
        invariant
            i <= input.len(),
            result.len() == i,
            forall|j: int| 0 <= j < input.len() ==> input[j]@.len() >= 1,
            forall|j: int| 0 <= j < i ==>
                if input[j]@.len() > width {
                    result[j]@.len() == input[j]@.len()
                } else {
                    result[j]@.len() == width
                },
            forall|j: int| 0 <= j < i ==>
                if input[j]@.len() < width {
                    let start_pos = (width - input[j]@.len() + 1) / 2;
                    result[j]@.skip(start_pos as int).take(input[j]@.len() as int) == input[j]@
                } else {
                    true
                },
        decreases input.len() - i
    {
        let s: &str = input[i].as_str();
        let n = s.unicode_len();
        if n >= width {
            let out = String::from_str(s);
            result.push(out);
        } else {
            let one = s.substring_char(0, 1);
            let mut out = String::from_str(s.substring_char(0, 0));
            let left: usize = (width - n + 1) / 2;
            let mut k: usize = 0;
            while k < left
                invariant
                    out@.len() == k,
                    k <= left,
                    one@.len() == 1,
                decreases left - k
            {
                out.append(one);
                k = k + 1;
            }
            out.append(s);
            assert(out@.subrange(left as int, left + n) =~= s@);
            let total: usize = width - n;
            while k < total
                invariant
                    left <= k <= total,
                    total + n == width,
                    out@.len() == k + n,
                    one@.len() == 1,
                    s@.len() == n,
                    out@.subrange(left as int, left + n) == s@,
                decreases total - k
            {
                let ghost prev = out@;
                out.append(one);
                assert(out@.subrange(left as int, left + n) =~= prev.subrange(left as int, left + n));
                k = k + 1;
            }
            assert(out@.skip(left as int).take(n as int) =~= s@);
            result.push(out);
        }
        i = i + 1;
    }
    result
}

}
