use vstd::prelude::*;

verus! {

fn clip(a: Vec<i8>, min: i8, max: i8) -> (result: Vec<i8>)
    requires min < max,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> {
            if a@[i] < min as int {
                result@[i] == min as int
            } else if a@[i] > max as int {
                result@[i] == max as int
            } else {
                result@[i] == a@[i]
            }
        }
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> {
                if a@[j] < min as int {
                    result@[j] == min as int
                } else if a@[j] > max as int {
                    result@[j] == max as int
                } else {
                    result@[j] == a@[j]
                }
            },
        decreases a.len() - i
    {
        let x = a[i];
        let v = if x < min { min } else if x > max { max } else { x };
        result.push(v);
        i += 1;
    }
    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

fn column_stack(input: Vec<Vec<i8>>, m: usize, n: usize) -> (result: Vec<Vec<i8>>)
    requires 
        n > 0,
        input@.len() == n,
        forall|i: int| 0 <= i < n ==> #[trigger] input@[i].len() == m,
    ensures
        result@.len() == m,
        forall|j: int| 0 <= j < m ==> result@[j].len() == n,
        result@.len() * n == m * n,
        forall|i: int, j: int| 0 <= i < n && 0 <= j < m ==> 
            result@[j][i] as int == input@[i][j] as int,
{
    let mut result: Vec<Vec<i8>> = Vec::new();
    let mut j: usize = 0;
    while j < m
        invariant
            0 <= j <= m,
            input@.len() == n,
            forall|i: int| 0 <= i < n ==> #[trigger] input@[i].len() == m,
            result@.len() == j,
            forall|jj: int| 0 <= jj < j ==> #[trigger] result@[jj].len() == n,
            forall|i: int, jj: int| 0 <= i < n && 0 <= jj < j ==>
                #[trigger] result@[jj][i] as int == input@[i][jj] as int,
        decreases m - j
    {
        let mut col: Vec<i8> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                0 <= i <= n,
                j < m,
                input@.len() == n,
                forall|k: int| 0 <= k < n ==> #[trigger] input@[k].len() == m,
                col@.len() == i,
                forall|k: int| 0 <= k < i ==> #[trigger] col@[k] == input@[k][j as int],
            decreases n - i
        {
            assert(input@[i as int].len() == m);
            col.push(input[i][j]);
            i += 1;
        }
        let ghost old_result = result@;
        result.push(col);
        assert(result@[j as int] == col);
        assert forall|jj: int| 0 <= jj < j + 1 implies #[trigger] result@[jj].len() == n by {
            if jj < j {
                assert(result@[jj] == old_result[jj]);
            }
        }
        assert forall|ii: int, jj: int| 0 <= ii < n && 0 <= jj < j + 1 implies
            #[trigger] result@[jj][ii] as int == input@[ii][jj] as int by {
            if jj < j {
                assert(result@[jj] == old_result[jj]);
            } else {
                assert(col@[ii] == input@[ii][j as int]);
            }
        }
        j += 1;
    }
    assert(result@.len() == m);
    result
}

}
