use vstd::prelude::*;

verus! {

#[verifier::exec_allows_no_decreases_clause]
fn cum_prod(a: Vec<i8>) -> (result: Vec<i8>)
    requires a.len() > 0,
    ensures 
        result.len() == a.len(),
        result[0] == a[0],
        forall|i: int| 0 < i < a.len() ==> result[i] as int == result[i-1] as int * a[i] as int
{
    let mut result: Vec<i8> = Vec::new();
    result.push(a[0]);
    let mut i: usize = 1;
    while i < a.len()
        invariant
            1 <= i <= a.len(),
            result.len() == i,
            result[0] == a[0],
            forall|j: int| 0 < j < i ==> result[j] as int == result[j-1] as int * a[j] as int,
        decreases a.len() - i
    {
        let prev = result[i - 1];
        let x = a[i];
        assert(-128 <= prev as int <= 127);
        assert(-128 <= x as int <= 127);
        assert(-16384 <= (prev as int) * (x as int) <= 16384) by (nonlinear_arith)
            requires -128 <= prev as int <= 127, -128 <= x as int <= 127;
        let p: i16 = (prev as i16) * (x as i16);
        if p < -128 || p > 127 {
            loop {}
        }
        result.push(p as i8);
        i += 1;
    }
    result
}

}
fn main() {}

use vstd::prelude::*;

verus! {

#[verifier::exec_allows_no_decreases_clause]
fn cum_sum(a: Vec<i8>) -> (result: Vec<i8>)
    requires a.len() > 0,
    ensures 
        result.len() == a.len(),
        result[0] == a[0],
        forall|i: int| 1 <= i < a.len() ==> result[i as int] as int == result[(i - 1) as int] as int + a[i as int] as int
{
    let mut result: Vec<i8> = Vec::new();
    result.push(a[0]);
    let mut i: usize = 1;
    while i < a.len()
        invariant
            1 <= i <= a.len(),
            result.len() == i,
