            forall|j: int| 0 <= j < arr.len() ==> arr[j].len() == arr.len(),
            forall|j: int| 0 <= j < i ==> result[j] == arr[j][j + off],
        decreases n - off - i
    {
        result.push(arr[i][i + off]);
        i += 1;
    }
