/* Matrix type definition - 2D array represented as vector of vectors */
pub struct Matrix {
    pub data: Vec<Vec<i32>>,
    pub rows: usize,
    pub cols: usize,
}

impl Matrix {
    pub open spec fn size(&self) -> nat {
        (self.rows * self.cols) as nat
    }

    pub open spec fn valid(&self) -> bool {
        &&& self.data.len() == self.rows
        &&& forall|i: int| 0 <= i < self.rows ==> self.data[i].len() == self.cols
    }

    pub open spec fn get(&self, i: usize, j: usize) -> i32 
        recommends self.valid() && i < self.rows && j < self.cols
    {
        self.data[i as int][j as int]
    }
}

fn flatten2(mat: &Matrix) -> (ret: Vec<i32>)
    requires 
        mat.rows > 0,
        mat.cols > 0,
        mat.valid(),
    ensures
        ret.len() == mat.rows * mat.cols,
        forall|i: int, j: int| 
            0 <= i < mat.rows && 0 <= j < mat.cols ==> 
            #[trigger] ret@[(i * (mat.cols as int) + j) as int] == mat.get(i as usize, j as usize),
{
    let mut ret: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    while i < mat.rows
        invariant
            0 <= i <= mat.rows,
            mat.cols > 0,
            mat.valid(),
            ret.len() == (i as int) * (mat.cols as int),
            forall|a: int, b: int|
                0 <= a < i && 0 <= b < mat.cols ==>
                #[trigger] ret@[(a * (mat.cols as int) + b) as int] == mat.get(a as usize, b as usize),
        decreases mat.rows - i,
    {
        let mut j: usize = 0;
        while j < mat.cols
            invariant
                0 <= i < mat.rows,
                0 <= j <= mat.cols,
                mat.cols > 0,
                mat.valid(),
                ret.len() == (i as int) * (mat.cols as int) + (j as int),
                forall|a: int, b: int|
                    0 <= a < i && 0 <= b < mat.cols ==>
                    #[trigger] ret@[(a * (mat.cols as int) + b) as int] == mat.get(a as usize, b as usize),
                forall|b: int|
                    0 <= b < j ==>
                    #[trigger] ret@[((i as int) * (mat.cols as int) + b) as int] == mat.get(i, b as usize),
            decreases mat.cols - j,
        {
            let ghost old_ret = ret@;
            ret.push(mat.data[i][j]);
            proof {
                let c = mat.cols as int;
                let ii = i as int;
                assert forall|a: int, b: int|
                    0 <= a < i && 0 <= b < mat.cols implies
                    #[trigger] ret@[(a * (mat.cols as int) + b) as int] == mat.get(a as usize, b as usize) by {
                    assert(a * c + b < ii * c) by(nonlinear_arith)
                        requires 0 <= a < ii, 0 <= b < c;
                    assert(ret@[(a * c + b) as int] == old_ret[(a * c + b) as int]);
                }
                assert forall|b: int|
                    0 <= b < j + 1 implies
                    #[trigger] ret@[((i as int) * (mat.cols as int) + b) as int] == mat.get(i, b as usize) by {
                    if b < j {
                        assert(ret@[(ii * c + b) as int] == old_ret[(ii * c + b) as int]);
                    } else {
                        assert(b == j);
                    }
                }
            }
            j = j + 1;
        }
        proof {
            let c = mat.cols as int;
            let ii = i as int;
            assert(ii * c + c == (ii + 1) * c) by(nonlinear_arith);
            assert forall|a: int, b: int|
                0 <= a < i + 1 && 0 <= b < mat.cols implies
                #[trigger] ret@[(a * (mat.cols as int) + b) as int] == mat.get(a as usize, b as usize) by {
                if a < ii {
                } else {
                    assert(a == ii);
                    assert(ret@[(ii * c + b) as int] == mat.get(i, b as usize));
                }
            }
        }
        i = i + 1;
    }
    ret
}

}
