use vstd::prelude::*;

verus! {

proof fn lemma_neg_mod(x: int, e: int)
    requires
        e > 0,
        x % e == 0,
    ensures
        (-x) % e == 0,
{
    vstd::arithmetic::div_mod::lemma_fundamental_div_mod(x, e);
    let q = x / e;
    assert(x == e * q);
    assert(-x == (-q) * e) by (nonlinear_arith)
        requires x == e * q;
    vstd::arithmetic::div_mod::lemma_mod_multiples_basic(-q, e);
}

proof fn lemma_div_abs(x: int, e: int)
    requires
        e > 0,
        x % e == 0,
    ensures
        (if x < 0 { -x } else { x }) % e == 0,
        x != 0 ==> e <= (if x < 0 { -x } else { x }),
{
    let ax = if x < 0 { -x } else { x };
    if x < 0 {
        lemma_neg_mod(x, e);
    }
    if x != 0 && e > ax {
        vstd::arithmetic::div_mod::lemma_small_mod(ax as nat, e as nat);
        assert(false);
    }
}

#[verifier::exec_allows_no_decreases_clause]
fn gcd_int(a: i8, b: i8) -> (result: i8)
    ensures
        result >= 0,
        (a as int) % (result as int) == 0,
        (b as int) % (result as int) == 0,
        forall|d: int| d > 0 && #[trigger] ((a as int) % d) == 0 && #[trigger] ((b as int) % d) == 0 ==> d <= (result as int),
{
    let ua: u16 = if a < 0 { (0i16 - a as i16) as u16 } else { a as u16 };
    let ub: u16 = if b < 0 { (0i16 - b as i16) as u16 } else { b as u16 };
    if ua % 128 == 0 && ub % 128 == 0 {
        loop {}
    }
    let mut d: u16 = 127;
    while d > 1
        invariant
            1 <= d <= 127,
            ua as int == (if a < 0 { -(a as int) } else { a as int }),
            ub as int == (if b < 0 { -(b as int) } else { b as int }),
            !(a == 0 && b == 0),
            forall|e: int| d < e <= 128 ==> !(#[trigger] ((ua as int) % e) == 0 && (ub as int) % e == 0),
        decreases d,
    {
        if ua % d == 0 && ub % d == 0 {
            proof {
                if a < 0 {
                    lemma_neg_mod(ua as int, d as int);
                }
                if b < 0 {
                    lemma_neg_mod(ub as int, d as int);
                }
                assert forall|e: int| e > 0 && #[trigger] ((a as int) % e) == 0 && #[trigger] ((b as int) % e) == 0 implies e <= d as int by {
                    lemma_div_abs(a as int, e);
                    lemma_div_abs(b as int, e);
                    assert((ua as int) % e == 0);
                    assert((ub as int) % e == 0);
                }
            }
            return d as i8;
        }
        d = d - 1;
    }
    proof {
        vstd::arithmetic::div_mod::lemma_mod_multiples_basic(a as int, 1);
        vstd::arithmetic::div_mod::lemma_mod_multiples_basic(b as int, 1);
        assert((a as int) * 1 == a as int);
        assert((b as int) * 1 == b as int);
        assert forall|e: int| e > 0 && #[trigger] ((a as int) % e) == 0 && #[trigger] ((b as int) % e) == 0 implies e <= 1 by {
            lemma_div_abs(a as int, e);
            lemma_div_abs(b as int, e);
            assert((ua as int) % e == 0);
            assert((ub as int) % e == 0);
        }
    }
    1
}

}
