verus! {
spec fn pow2(n: nat) -> nat 
    decreases n
{
    if n == 0 {
        1nat
    } else {
        2nat * pow2((n - 1) as nat)
    }
}

proof fn pow2_mono(k: nat, n: nat)
    requires k <= n
    ensures pow2(k) <= pow2(n)
    decreases n
{
    if k < n {
        pow2_mono(k, (n - 1) as nat);
        assert(pow2(n) == 2 * pow2((n - 1) as nat));
    }
}

proof fn pow2_ge1(k: nat)
    ensures pow2(k) >= 1
    decreases k
{
    if k > 0 {
        pow2_ge1((k - 1) as nat);
    }
}

#[verifier::exec_allows_no_decreases_clause]
fn invert(bit_width: u32, a: Vec<u32>) -> (result: Vec<u32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == (pow2(bit_width as nat) - 1) - a@[i]
{
    if bit_width > 32 {
        if a.len() == 0 {
            return Vec::new();
        }
        loop {}
    }
    proof {
        assert(pow2(32) == 4294967296nat) by(compute);
    }
    let mut m: u64 = 1;
    let mut k: u32 = 0;
    while k < bit_width
        invariant
            k <= bit_width,
            bit_width <= 32,
            m as nat == pow2(k as nat),
            pow2(32) == 4294967296nat,
        decreases bit_width - k
    {
        proof {
            pow2_mono((k + 1) as nat, 32);
            assert(pow2((k + 1) as nat) == 2 * pow2(k as nat));
        }
        m = m * 2;
        k = k + 1;
    }
    proof {
        pow2_ge1(bit_width as nat);
        pow2_mono(bit_width as nat, 32);
    }
    let mask: u32 = (m - 1) as u32;
    assert(mask as int == pow2(bit_width as nat) - 1);
    let mut result: Vec<u32> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            mask as int == pow2(bit_width as nat) - 1,
            forall|j: int| 0 <= j < i ==> result@[j] == (pow2(bit_width as nat) - 1) - a@[j],
        decreases a.len() - i
    {
        let x = a[i];
        if x > mask {
            loop {}
        }
        result.push(mask - x);
        i = i + 1;
    }
    result
}

}
