spec fn is_alpha_char(c: char) -> bool {
    ('A' <= c && c <= 'Z') || ('a' <= c && c <= 'z')
}

spec fn string_is_alpha(s: Seq<char>) -> bool {
    s.len() > 0 && forall|i: int| 0 <= i < s.len() ==> is_alpha_char(s[i])
}

fn is_alpha(input: Vec<String>) -> (ret: Vec<bool>)
    ensures
        ret.len() == input.len(),
        forall|i: int| 0 <= i < input.len() ==> 
            ret[i] == string_is_alpha(input[i]@)
{
    let mut ret: Vec<bool> = Vec::new();
    let mut i: usize = 0;
    while i < input.len()
        invariant
            i <= input.len(),
            ret.len() == i,
            forall|j: int| 0 <= j < i ==> ret[j] == string_is_alpha(input[j]@),
        decreases input.len() - i,
    {
        let s = input[i].as_str();
        let n = s.unicode_len();
        let mut ok: bool = n > 0;
        let mut k: usize = 0;
        while k < n
            invariant
                i < input.len(),
                n == s@.len(),
                s@ == input[i as int]@,
                k <= n,
                ok == (n > 0 && forall|m: int| 0 <= m < k ==> is_alpha_char(s@[m])),
            decreases n - k,
        {
            let c = s.get_char(k);
            if !(('A' <= c && c <= 'Z') || ('a' <= c && c <= 'z')) {
                ok = false;
            }
            k += 1;
        }
        ret.push(ok);
        i += 1;
    }
    ret
}

}
