spec fn all_nonzero(v: Seq<i32>) -> bool {
    forall|i: int| 0 <= i < v.len() ==> v[i] != 0
}

proof fn lemma_mod_unique(x: int, y: int, d: int, q: int, r: int)
    requires
        y != 0,
        d == (if y > 0 { y } else { -y }),
        x == q * d + r,
        0 <= r < d,
    ensures
        x % y == r,
{
    vstd::arithmetic::div_mod::lemma_fundamental_div_mod(x, y);
    let q0 = x / y;
    let r0 = x % y;
    assert(0 <= r0 < d);
    let qq = if y > 0 { q } else { -q };
    assert(qq * y == q * d) by (nonlinear_arith)
        requires
            d == (if y > 0 { y } else { -y }),
            qq == (if y > 0 { q } else { -q });
    assert((q0 - qq) * y == r - r0) by (nonlinear_arith)
        requires
            x == y * q0 + r0,
            x == qq * y + r;
    if q0 > qq {
        if y > 0 {
            assert((q0 - qq) * y >= y) by (nonlinear_arith)
                requires q0 - qq >= 1, y > 0;
        } else {
            assert((q0 - qq) * y <= y) by (nonlinear_arith)
                requires q0 - qq >= 1, y < 0;
        }
    }
    if q0 < qq {
        if y > 0 {
            assert((q0 - qq) * y <= -y) by (nonlinear_arith)
                requires q0 - qq <= -1, y > 0;
        } else {
            assert((q0 - qq) * y >= -y) by (nonlinear_arith)
                requires q0 - qq <= -1, y < 0;
        }
    }
    assert(q0 == qq);
    assert((q0 - qq) * y == 0) by (nonlinear_arith)
        requires q0 == qq;
}

fn mod_vec(a: Vec<i32>, b: Vec<i32>) -> (result: Vec<i32>)
    requires 
        a.len() == b.len(),
        all_nonzero(b@),
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == a[i] % b[i],
{
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            all_nonzero(b@),
            0 <= i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> #[trigger] result[j] == a[j] % b[j],
        decreases a.len() - i,
    {
        let x: i64 = a[i] as i64;
        let y: i64 = b[i] as i64;
        assert(b@[i as int] != 0);
        let ax: u64 = if x >= 0 { x as u64 } else { (-x) as u64 };
        let my: u64 = if y >= 0 { y as u64 } else { (-y) as u64 };
        let t: u64 = ax % my;
        proof {
            vstd::arithmetic::div_mod::lemma_fundamental_div_mod(ax as int, my as int);
            vstd::arithmetic::div_mod::lemma_mod_pos_bound(ax as int, my as int);
        }
        let r: i64 = if x >= 0 {
            t as i64
        } else if t == 0 {
            0
        } else {
            my as i64 - t as i64
        };
        proof {
            let qa: int = (ax as int) / (my as int);
            let m: int = my as int;
            assert(ax as int == m * qa + t as int);
            let qd: int = if x >= 0 { qa } else if t == 0 { -qa } else { -qa - 1 };
            if x >= 0 {
                assert(x as int == qd * m + r as int) by (nonlinear_arith)
                    requires x as int == ax as int, ax as int == m * qa + t as int,
                        qd == qa, r as int == t as int;
            } else if t == 0 {
                assert(x as int == qd * m + r as int) by (nonlinear_arith)
                    requires x as int == -(ax as int), ax as int == m * qa + t as int,
                        qd == -qa, r as int == 0, t as int == 0;
            } else {
                assert(x as int == qd * m + r as int) by (nonlinear_arith)
                    requires x as int == -(ax as int), ax as int == m * qa + t as int,
                        qd == -qa - 1, r as int == m - t as int;
            }
            lemma_mod_unique(x as int, y as int, m, qd, r as int);
        }
        result.push(r as i32);
        i = i + 1;
    }
    result
}

}
fn main() {}

