    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result[j] as int == a[j] as int * b[j] as int,
        decreases a.len() - i
    {
        let x: i16 = a[i] as i16;
        let y: i16 = b[i] as i16;
        assert(-16384 <= (x as int) * (y as int) <= 16384) by (nonlinear_arith)
            requires -128 <= x <= 127, -128 <= y <= 127;
        let p: i16 = x * y;
        if p >= -128 && p <= 127 {
            result.push(p as i8);
        } else {
            loop {}
        }
        i += 1;
    }
    result
