verus! {

fn polyder(poly: Vec<i8>, m: i8) -> (result: Vec<i8>)
    requires 
        m > 0,
        m <= poly.len() as i8,
    ensures 
        result.len() == poly.len() - (m as usize),
{
    proof {
        if poly.len() < 128 {
            assert(poly.len() as i8 == poly.len() as int);
        }
    }
    assert(m as usize <= poly.len());
    let n: usize = poly.len() - (m as usize);
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            result.len() == i,
            i <= n,
        decreases n - i,
    {
        result.push(0);
        i = i + 1;
    }
    result
}

