use vstd::prelude::*;

verus! {
spec fn int_pow(base: int, exp: nat) -> int
    decreases exp
{
    if exp == 0 {
        1
    } else {
        base * int_pow(base, (exp - 1) as nat)
    }
}

#[verifier::exec_allows_no_decreases_clause]
fn power(a: Vec<i8>, b: Vec<u8>) -> (result: Vec<i8>)
    requires a.len() == b.len(),
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < a@.len() ==> result@[i] == int_pow(a@[i] as int, b@[i] as nat),
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            a.len() == b.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> result@[j] == int_pow(a@[j] as int, b@[j] as nat),
        decreases a.len() - i
    {
        let base: i8 = a[i];
        let e: u8 = b[i];
        let mut acc: i8 = 1;
        let mut k: u8 = 0;
        while k < e
            invariant
                k <= e,
                acc as int == int_pow(base as int, k as nat),
                0 <= i < a.len(),
                a.len() == b.len(),
                result.len() == i,
                base == a@[i as int],
                e == b@[i as int],
                forall|j: int| 0 <= j < i ==> result@[j] == int_pow(a@[j] as int, b@[j] as nat),
            decreases e - k
        {
            assert(-16384 <= (base as int) * (acc as int) <= 16384) by (nonlinear_arith)
                requires
                    -128 <= base as int <= 127,
                    -128 <= acc as int <= 127,
            ;
            let p: i16 = (base as i16) * (acc as i16);
            if p < -128 || p > 127 {
                loop {}
            }
            acc = p as i8;
            k = k + 1;
            assert(int_pow(base as int, k as nat) == base as int * int_pow(base as int, (k - 1) as nat));
        }
        result.push(acc);
        i = i + 1;
    }
    result
}

}
