use vstd::prelude::*;

verus! {

proof fn lemma_mod_unique(x: int, y: int, q: int, r: int)
    requires
        y != 0,
        x == q * y + r,
        0 <= r,
        y > 0 ==> r < y,
        y < 0 ==> r < -y,
    ensures
        x % y == r,
{
    vstd::arithmetic::div_mod::lemma_fundamental_div_mod(x, y);
    let q2 = x / y;
    let r2 = x % y;
    assert(0 <= r2 && (y > 0 ==> r2 < y) && (y < 0 ==> r2 < -y)) by (nonlinear_arith)
        requires y != 0, r2 == x % y;
    if y > 0 {
        assert(q == q2) by (nonlinear_arith)
            requires
                x == q * y + r,
                x == y * q2 + r2,
                0 <= r < y,
                0 <= r2 < y,
                y > 0;
    } else {
        assert(q == q2) by (nonlinear_arith)
            requires
                x == q * y + r,
                x == y * q2 + r2,
                0 <= r < -y,
                0 <= r2 < -y,
                y < 0;
    }
    assert(r == r2) by (nonlinear_arith)
        requires x == q * y + r, x == y * q2 + r2, q == q2;
}

fn remainder(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<i8>)
    requires 
        a.len() == b.len(),
        forall|i: int| 0 <= i < b.len() ==> b[i] != 0,
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> result[i] == a[i] % b[i],
{
    let mut res: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            forall|k: int| 0 <= k < b.len() ==> b[k] != 0,
            0 <= i <= a.len(),
            res.len() == i,
            forall|j: int| 0 <= j < i ==> res[j] == a[j] % b[j],
        decreases a.len() - i,
    {
        let x: i32 = a[i] as i32;
        let y: i32 = b[i] as i32;
        assert(y != 0);
        let m: u32 = if y < 0 { (-y) as u32 } else { y as u32 };
        assert(1 <= m <= 128);
        let r: u32;
        if x >= 0 {
            let xu: u32 = x as u32;
            r = xu % m;
            proof {
                let xi = x as int;
                let yi = y as int;
                let mi = m as int;
                vstd::arithmetic::div_mod::lemma_fundamental_div_mod(xi, mi);
                let q = xi / mi;
                assert(xi % mi == r as int);
                assert(xi == mi * q + r as int);
                if y > 0 {
                    assert(xi == q * yi + r as int) by (nonlinear_arith)
                        requires xi == mi * q + r as int, yi == mi;
                    lemma_mod_unique(xi, yi, q, r as int);
                } else {
                    assert(xi == (-q) * yi + r as int) by (nonlinear_arith)
                        requires xi == mi * q + r as int, yi == -mi;
                    lemma_mod_unique(xi, yi, -q, r as int);
                }
            }
        } else {
            let nxu: u32 = (-x) as u32;
            let r0: u32 = nxu % m;
            if r0 == 0 {
                r = 0;
            } else {
                r = m - r0;
            }
            proof {
                let xi = x as int;
                let yi = y as int;
                let mi = m as int;
                let nx = -xi;
                vstd::arithmetic::div_mod::lemma_fundamental_div_mod(nx, mi);
                let q0 = nx / mi;
                assert(nx % mi == r0 as int);
                assert(nx == mi * q0 + r0 as int);
                let q: int = if r0 == 0 { -q0 } else { -q0 - 1 };
                assert(xi == mi * q + r as int) by (nonlinear_arith)
                    requires
                        nx == mi * q0 + r0 as int,
                        xi == -nx,
                        q == (if r0 == 0 { -q0 } else { -q0 - 1 }),
                        r as int == (if r0 == 0 { 0 } else { mi - r0 as int });
                if y > 0 {
                    assert(xi == q * yi + r as int) by (nonlinear_arith)
                        requires xi == mi * q + r as int, yi == mi;
                    lemma_mod_unique(xi, yi, q, r as int);
                } else {
                    assert(xi == (-q) * yi + r as int) by (nonlinear_arith)
                        requires xi == mi * q + r as int, yi == -mi;
                    lemma_mod_unique(xi, yi, -q, r as int);
                }
            }
        }
        assert(r < 128);
        let v: i8 = r as i8;
        assert(v as int == r as int);
        assert(v == a[i as int] % b[i as int]);
        res.push(v);
        i += 1;
    }
    res
}

}
