use vstd::prelude::*;

verus! {

type Matrix<T> = Vec<Vec<T>>;

spec fn matrix_size<T>(mat: Matrix<T>) -> nat {
    if mat.len() == 0 { 0 } else { (mat.len() * mat[0].len()) as nat }
}

spec fn get_matrix_element<T>(mat: Matrix<T>, i: nat, j: nat) -> T {
    mat[i as int][j as int]
}

spec fn get_vector_element<T>(arr: Seq<T>, i: nat) -> T {
    arr[i as int]
}

fn reshape(arr: Vec<i32>, shape: Vec<usize>) -> (result: Matrix<i32>)
    requires 
        arr.len() > 0,
        shape.len() == 2,
        forall|i: int| 0 <= i < 2 ==> (shape[i] > 0 || shape[i] == 0),
        !(shape[0] == 0 && shape[1] == 0),
        (if shape[0] > 0 && shape[1] > 0 { 
            shape[0] * shape[1] == arr.len()
        } else if shape[0] == 0 { 
            arr.len() % shape[1] == 0
        } else { 
            arr.len() % shape[0] == 0
        }),
    ensures
        result.len() > 0,
        result[0].len() > 0,
        (if shape[0] > 0 { 
            matrix_size(result) / (if shape[1] > 0 { shape[1] as nat } else { (arr.len() / shape[0]) as nat }) == shape[0] as nat
        } else { 
            matrix_size(result) / (if shape[1] > 0 { shape[1] as nat } else { (arr.len() / shape[0]) as nat }) == (arr.len() / shape[1]) as nat
        }),
        forall|i: nat| i < arr.len() ==> #[trigger] get_vector_element(arr@, i) == result[((i as usize) / result[0].len()) as int][((i as usize) % result[0].len()) as int]
{
    let len = arr.len();
    let rows: usize;
    let cols: usize;
    if shape[0] > 0 && shape[1] > 0 {
        rows = shape[0];
        cols = shape[1];
    } else if shape[0] == 0 {
        cols = shape[1];
        rows = len / cols;
        proof { vstd::arithmetic::div_mod::lemma_fundamental_div_mod(len as int, cols as int); }
    } else {
        rows = shape[0];
        cols = len / rows;
        proof { vstd::arithmetic::div_mod::lemma_fundamental_div_mod(len as int, rows as int); }
    }
    assert(rows * cols == cols * rows) by(nonlinear_arith);
    assert(rows * cols == len);
    assert(rows > 0 && cols > 0) by(nonlinear_arith)
        requires rows * cols == len, len > 0;

    let mut result: Vec<Vec<i32>> = Vec::new();
    let mut r: usize = 0;
    while r < rows
        invariant
            result.len() == r,
            r <= rows,
            rows * cols == len,
            len == arr.len(),
            cols > 0,
            forall|rr: int| 0 <= rr < r ==> #[trigger] result[rr].len() == cols,
            forall|rr: int, cc: int| 0 <= rr < r && 0 <= cc < cols ==>
                #[trigger] result[rr][cc] == arr[rr * cols + cc],
        decreases rows - r
    {
        let mut row: Vec<i32> = Vec::new();
        let mut c: usize = 0;
        while c < cols
            invariant
                row.len() == c,
                c <= cols,
                r < rows,
                result.len() == r,
                rows * cols == len,
                len == arr.len(),
                cols > 0,
                forall|rr: int| 0 <= rr < r ==> #[trigger] result[rr].len() == cols,
                forall|rr: int, cc: int| 0 <= rr < r && 0 <= cc < cols ==>
                    #[trigger] result[rr][cc] == arr[rr * cols + cc],
                forall|cc: int| 0 <= cc < c ==> #[trigger] row[cc] == arr[r * cols + cc],
            decreases cols - c
        {
            assert(r * cols + c < rows * cols) by(nonlinear_arith)
                requires r < rows, c < cols;
            row.push(arr[r * cols + c]);
            c += 1;
        }
        result.push(row);
        r += 1;
    }

    proof {
        vstd::arithmetic::div_mod::lemma_div_multiples_vanish(rows as int, cols as int);
        assert((cols * rows) / (cols as int) == rows as int);
        assert(matrix_size(result) == (rows * cols) as nat);
    }

    assert forall|i: nat| i < arr.len() implies #[trigger] get_vector_element(arr@, i) == result[((i as usize) / result[0].len()) as int][((i as usize) % result[0].len()) as int] by {
        let ii = i as int;
        let c = cols as int;
        vstd::arithmetic::div_mod::lemma_fundamental_div_mod(ii, c);
        vstd::arithmetic::div_mod::lemma_mod_pos_bound(ii, c);
        vstd::arithmetic::div_mod::lemma_div_pos_is_pos(ii, c);
        let q = ii / c;
        let m = ii % c;
        assert(q < rows as int) by(nonlinear_arith)
            requires ii == c * q + m, 0 <= m, ii < (rows as int) * c, c > 0, q >= 0;
        assert(q * c + m == ii) by(nonlinear_arith)
            requires ii == c * q + m;
        assert(result[q][m] == arr[q * cols + m]);
    }

    result
}

}
