use vstd::prelude::*;
use vstd::arithmetic::power2::pow2;

verus! {
spec fn shift_right_int(x: int, n: nat) -> int {
    if x >= 0 {
        x / (pow2(n) as int)
    } else {
        -((((-x) - 1) / (pow2(n) as int)) + 1)
    }
}

fn right_shift(a: Vec<i32>, b: Vec<u32>) -> (result: Vec<i32>)
    requires 
        a.len() == b.len(),
        forall|i: int| 0 <= i < b.len() ==> b[i] < 64,
    ensures 
        result.len() == a.len(),
        forall|i: int| 0 <= i < result.len() ==> 
            result[i] as int == shift_right_int(a[i] as int, b[i] as nat),
{
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            a.len() == b.len(),
            forall|j: int| 0 <= j < b.len() ==> b[j] < 64,
            0 <= i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> 
                result[j] as int == shift_right_int(a[j] as int, b[j] as nat),
        decreases a.len() - i,
    {
        let x: i64 = a[i] as i64;
        let n: u32 = b[i];
        let u: u64 = if x >= 0 { x as u64 } else { (-x - 1) as u64 };
        assert(u < 0x100000000);
        let q: u64;
        if n >= 32 {
            q = 0;
            proof {
                vstd::arithmetic::power2::lemma2_to64();
                if n > 32 {
                    vstd::arithmetic::power2::lemma_pow2_strictly_increases(32, n as nat);
                }
                let pp = pow2(n as nat) as int;
                assert(pp >= 0x100000000);
                let ui = u as int;
                assert(ui / pp == 0) by (nonlinear_arith)
                    requires 0 <= ui < pp;
            }
        } else {
            let mut p: u64 = 1;
            let mut k: u32 = 0;
            proof {
                vstd::arithmetic::power2::lemma2_to64();
            }
            while k < n
                invariant
                    k <= n,
                    n < 32,
                    p as int == pow2(k as nat) as int,
                decreases n - k,
            {
                proof {
                    vstd::arithmetic::power2::lemma2_to64();
                    vstd::arithmetic::power2::lemma_pow2_strictly_increases(k as nat, 32);
                    vstd::arithmetic::power2::lemma_pow2_unfold((k + 1) as nat);
                }
                p = p * 2;
                k = k + 1;
            }
            proof {
                vstd::arithmetic::power2::lemma_pow2_pos(n as nat);
            }
            q = u / p;
            proof {
                let ui = u as int;
                let pi = p as int;
                assert(0 <= ui / pi <= ui) by (nonlinear_arith)
                    requires 0 <= ui, pi >= 1;
            }
        }
        proof {
            assert(q as int == (u as int) / (pow2(n as nat) as int));
            assert(q <= u) by {
                vstd::arithmetic::power2::lemma_pow2_pos(n as nat);
                let ui = u as int;
                let pi = pow2(n as nat) as int;
                assert(0 <= ui / pi <= ui) by (nonlinear_arith)
                    requires 0 <= ui, pi >= 1;
            }
        }
        let r: i32 = if x >= 0 { q as i32 } else { (-(q as i64) - 1) as i32 };
        result.push(r);
        proof {
            assert(result[i as int] as int == shift_right_int(a[i as int] as int, b[i as int] as nat));
        }
        i = i + 1;
    }
    result
}

}
