        result@.len() == condlist@[0].len(),
        forall|i: int, j: int| 
            0 <= i < condlist@.len() && 0 <= j < result@.len() && condlist@[i][j] ==> 
            result@[j] == choicelist@[i][j],
{
    let n = condlist[0].len();
    let m = condlist.len();
    let mut result: Vec<f32> = Vec::new();
    let mut j: usize = 0;
    while j < n
        invariant
            n == condlist@[0].len(),
            m == condlist@.len(),
            condlist@.len() > 0,
            condlist@.len() == choicelist@.len(),
            forall|i: int| 0 <= i < condlist@.len() ==> condlist@[i].len() == choicelist@[i].len(),
            forall|i: int, k: int| 0 <= i < condlist@.len() && 0 <= k < condlist@.len() ==> 
                condlist@[i].len() == condlist@[k].len(),
            j <= n,
            result@.len() == j,
            forall|i: int, k: int| 0 <= i < m && 0 <= k < j && condlist@[i][k] ==>
                result@[k] == choicelist@[i][k],
        decreases n - j
    {
        let mut found = false;
        let mut val: f32 = 0.0;
        let mut idx: usize = 0;
        let mut i: usize = 0;
        while i < m
            invariant
                n == condlist@[0].len(),
                m == condlist@.len(),
                condlist@.len() > 0,
                condlist@.len() == choicelist@.len(),
                forall|a: int| 0 <= a < condlist@.len() ==> condlist@[a].len() == choicelist@[a].len(),
                forall|a: int, b: int| 0 <= a < condlist@.len() && 0 <= b < condlist@.len() ==> 
