fn sign(a: Vec<i32>) -> (result: Vec<i32>)
    ensures
        result.len() == a.len(),
        forall|i: int| 0 <= i < a.len() ==> {
            (a[i] > 0 ==> result[i] == 1) &&
            (a[i] == 0 ==> result[i] == 0) &&
            (a[i] < 0 ==> result[i] == -1)
        }
{
    let mut result: Vec<i32> = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> {
                (a[j] > 0 ==> result[j] == 1) &&
                (a[j] == 0 ==> result[j] == 0) &&
                (a[j] < 0 ==> result[j] == -1)
            },
        decreases a.len() - i,
    {
        let v = a[i];
        if v > 0 {
            result.push(1);
        } else if v == 0 {
            result.push(0);
        } else {
            result.push(-1);
        }
        i += 1;
    }
    result
}

