use vstd::prelude::*;

verus! {
spec fn multiset_count<T>(s: Seq<T>, x: T) -> nat {
    s.filter(|y| y == x).len()
}

proof fn lemma_count_push(s: Seq<i8>, v: i8, x: i8)
    ensures multiset_count(s.push(v), x) == multiset_count(s, x) + (if v == x { 1nat } else { 0nat })
{
    reveal_with_fuel(Seq::<i8>::filter, 2);
    let t = s.push(v);
    assert(t.drop_last() =~= s);
    assert(t.last() == v);
    assert(t.len() != 0);
}

proof fn lemma_count_empty(s: Seq<i8>, x: i8)
    requires s.len() == 0,
    ensures multiset_count(s, x) == 0
{
    reveal_with_fuel(Seq::<i8>::filter, 2);
}

proof fn lemma_count_add(a: Seq<i8>, b: Seq<i8>, x: i8)
    ensures multiset_count(a + b, x) == multiset_count(a, x) + multiset_count(b, x)
    decreases b.len()
{
    if b.len() == 0 {
        assert(a + b =~= a);
        lemma_count_empty(b, x);
    } else {
        let b2 = b.drop_last();
        let l = b.last();
        lemma_count_add(a, b2, x);
        assert(a + b =~= (a + b2).push(l));
        assert(b =~= b2.push(l));
        lemma_count_push(a + b2, l, x);
        lemma_count_push(b2, l, x);
    }
}

fn sort(a: Vec<i8>) -> (result: Vec<i8>)
    ensures
        result.len() == a.len(),
        forall|i: int, j: int| 0 <= i < j < result.len() ==> result[i] as int <= result[j] as int,
        forall|x: i8| multiset_count(result@, x) == multiset_count(a@, x),
{
    let mut result: Vec<i8> = Vec::new();
    let mut i: usize = 0;
    proof {
        assert forall|x: i8| multiset_count(result@, x) == multiset_count(a@.subrange(0, 0), x) by {
            lemma_count_empty(result@, x);
            lemma_count_empty(a@.subrange(0, 0), x);
        }
    }
    while i < a.len()
        invariant
            i <= a.len(),
            result.len() == i,
            forall|p: int, q: int| 0 <= p < q < result.len() ==> result[p] as int <= result[q] as int,
            forall|x: i8| multiset_count(result@, x) == multiset_count(a@.subrange(0, i as int), x),
        decreases a.len() - i
    {
        let v = a[i];
        let mut k: usize = 0;
        while k < result.len() && result[k] <= v
            invariant
                i < a.len(),
                v == a[i as int],
                result.len() == i,
                k <= result.len(),
                forall|j: int| 0 <= j < k ==> result[j] as int <= v as int,
                forall|p: int, q: int| 0 <= p < q < result.len() ==> result[p] as int <= result[q] as int,
            decreases result.len() - k
        {
            k += 1;
        }
        let ghost old_r = result@;
        proof {
            assert forall|j: int| k <= j < old_r.len() implies old_r[j] as int > v as int by {
                if j > k as int {
                    assert(old_r[k as int] as int <= old_r[j] as int);
                }
            }
        }
        result.insert(k, v);
        proof {
            assert(result@ == old_r.insert(k as int, v));
            assert forall|j: int| 0 <= j < k implies result@[j] == old_r[j] by {}
            assert(result@[k as int] == v);
            assert forall|j: int| k < j < result.len() implies result@[j] == old_r[j - 1] by {}
            assert forall|p: int, q: int| 0 <= p < q < result.len() implies result[p] as int <= result[q] as int by {
                if q < k {
                    assert(result@[p] == old_r[p]);
                    assert(result@[q] == old_r[q]);
                } else if q == k {
                    assert(result@[p] == old_r[p]);
                } else if p < k {
                    assert(result@[p] == old_r[p]);
                    assert(result@[q] == old_r[q - 1]);
                } else if p == k {
                    assert(result@[q] == old_r[q - 1]);
                } else {
                    assert(result@[p] == old_r[p - 1]);
                    assert(result@[q] == old_r[q - 1]);
                }
            }
            let pp = old_r.subrange(0, k as int);
            let qq = old_r.subrange(k as int, old_r.len() as int);
            assert(result@ =~= pp.push(v) + qq);
            assert(old_r =~= pp + qq);
            assert(a@.subrange(0, i as int + 1) =~= a@.subrange(0, i as int).push(v));
            assert forall|x: i8| multiset_count(result@, x) == multiset_count(a@.subrange(0, i as int + 1), x) by {
                lemma_count_add(pp.push(v), qq, x);
                lemma_count_push(pp, v, x);
                lemma_count_add(pp, qq, x);
                lemma_count_push(a@.subrange(0, i as int), v, x);
            }
        }
        i += 1;
    }
    proof {
        assert(a@.subrange(0, a.len() as int) =~= a@);
    }
    result
}

}
