use vstd::prelude::*;

verus! {

type Matrix<T> = Vec<Vec<T>>;

spec fn matrix_size<T>(m: Matrix<T>) -> nat {
    (m.len() * (if m.len() > 0 { m[0].len() } else { 0 })) as nat
}

#[verifier::exec_allows_no_decreases_clause]
fn tril(arr: Matrix<i8>, k: i8) -> (ret: Matrix<i8>)
    requires 
        arr.len() > 0,
        arr[0].len() > 0,
        -((arr.len() as i8) - 1) < k && k < (arr[0].len() as i8) - 1,
    ensures
        matrix_size(ret) == matrix_size(arr),
        ret.len() == arr.len(),
        forall|i: int, j: int| 
            0 <= i < arr.len() && 0 <= j < arr[0].len() ==> 
                if j - i > k as int { ret[i][j] == 0 } else { ret[i][j] == arr[i][j] }
{
    let n = arr.len();
    let m = arr[0].len();
    let mut ret: Vec<Vec<i8>> = Vec::new();
    let mut i: usize = 0;
    while i < n
        invariant
            n == arr.len(),
            m == arr[0].len(),
            i <= n,
            ret.len() == i,
            forall|ii: int| 0 <= ii < i ==> #[trigger] ret[ii].len() == m,
            forall|ii: int, j: int| 0 <= ii < i && 0 <= j < m ==>
                if j - ii > k as int { ret[ii][j] == 0 } else { ret[ii][j] == arr[ii][j] },
        decreases n - i
    {
        if arr[i].len() < m {
            loop {}
        }
        let mut row: Vec<i8> = Vec::new();
        let mut j: usize = 0;
        while j < m
            invariant
                n == arr.len(),
                m == arr[0].len(),
                i < n,
                arr[i as int].len() >= m,
                j <= m,
                row.len() == j,
                forall|jj: int| 0 <= jj < j ==>
                    if jj - i > k as int { row[jj] == 0 } else { row[jj] == arr[i as int][jj] },
            decreases m - j
        {
            let cond: bool = if k >= 0 {
                j > i && j - i > k as usize
            } else {
                let nk: usize = (-(k as i16)) as usize;
                j >= i || i - j < nk
            };
            assert(cond == (j - i > k as int));
            if cond {
                row.push(0);
            } else {
                row.push(arr[i][j]);
            }
            j = j + 1;
        }
        ret.push(row);
        i = i + 1;
    }
    assert(ret[0].len() == m);
    ret
}

}
